// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this));
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        try c.withdrawAll(actor) {} catch {}
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore);
    }
}
